"""Arc-eager transition parsing driven by a static oracle, plus one perceptron update."""
import numpy as np

words = ["ROOT", "He", "sent", "her", "a", "letter", "."]
gold = {1: (2, "SBJ"), 2: (0, "ROOT"), 3: (2, "IOBJ"), 4: (5, "DET"), 5: (2, "DOBJ"), 6: (2, "PUNC")}  # dep: (head, label)

def oracle(stack, buf, arcs):
    s, b = stack[-1], buf[0]
    if gold.get(s, (None,))[0] == b and s != 0:
        return "LA"
    if gold[b][0] == s:
        return "RA"
    # reduce if s already has its head and all of its dependents
    if s in arcs and all(d in arcs for d, (h, _) in gold.items() if h == s):
        return "RE"
    return "SH"

stack, buf, arcs = [0], list(range(1, len(words))), {}
print(f"{'action':6s} {'stack':28s} {'buffer':26s} arc")
while buf:
    t = oracle(stack, buf, arcs); new = ""
    if t == "SH": stack.append(buf.pop(0))
    elif t == "LA":
        d = stack.pop(); arcs[d] = gold[d]; new = f"{words[buf[0]]} -{gold[d][1]}-> {words[d]}"
    elif t == "RA":
        d = buf.pop(0); arcs[d] = gold[d]; stack.append(d); new = f"{words[gold[d][0]]} -{gold[d][1]}-> {words[d]}"
    elif t == "RE": stack.pop()
    print(f"{t:6s} {str([words[i] for i in stack]):28s} {str([words[i] for i in buf]):26s} {new}")
print("all gold arcs recovered:", arcs == gold, f"({len(arcs)} arcs, linear number of transitions)")

# Perceptron update on one mistaken decision
feats = ["stack_empty", "stackN_bufV", "stackV_bufN"]
f = {"SH": np.array([0, 1, 0]), "LA": np.array([0, 1, 0])}   # same configuration features, per-action weights
W = {"SH": np.array([5.0, 5.0, 5.0]), "LA": np.array([5.5, 5.5, 5.5])}
pred = max(W, key=lambda t: W[t] @ f[t]); gold_t = "SH"
print(f"scores: SH {W['SH'] @ f['SH']}, LA {W['LA'] @ f['LA']} -> predicted {pred}, oracle wanted {gold_t}")
W[gold_t] = W[gold_t] + f[gold_t]; W[pred] = W[pred] - f[pred]
print(f"after update: SH {W['SH'].tolist()} (score {W['SH'] @ f['SH']}), LA {W['LA'].tolist()} (score {W['LA'] @ f['LA']})")

"""Graph-based dependency parsing: Chu-Liu-Edmonds on 'John saw Mary', checked by brute force."""
from itertools import product

W = {(0, 1): 9, (0, 2): 10, (0, 3): 9,          # root -> John, saw, Mary
     (2, 1): 30, (2, 3): 30, (1, 2): 20, (3, 2): 0, (1, 3): 3, (3, 1): 11}
names = ["root", "John", "saw", "Mary"]

def find_cycle(head):
    for start in head:
        seen, v = [], start
        while v in head and v not in seen:
            seen.append(v); v = head[v]
        if v in seen:
            return seen[seen.index(v):]
    return None

def cle(nodes, W):
    head = {v: max((u for u in nodes if (u, v) in W), key=lambda u: W[(u, v)]) for v in nodes if v != 0}
    cyc = find_cycle(head)
    if not cyc: return head
    C = set(cyc); c = max(nodes) + 1; sC = sum(W[(head[v], v)] for v in C)
    print(f"  cycle {[names[v] if v < len(names) else v for v in cyc]} with internal score {sC}; contract into node {c}")
    W2, origin = {}, {}
    for (u, v), w in W.items():
        if u not in C and v in C:
            nw = w - W[(head[v], v)] + sC                      # enter v, break v's internal arc
            if nw > W2.get((u, c), -1e9): W2[(u, c)] = nw; origin[(u, c)] = (u, v)
        elif u in C and v not in C:
            if w > W2.get((c, v), -1e9): W2[(c, v)] = w; origin[(c, v)] = (u, v)
        elif u not in C and v not in C:
            W2[(u, v)] = w; origin[(u, v)] = (u, v)
    for k, w in W2.items():
        if c in k: print(f"    {('C' if k[0]==c else names[k[0]])} -> {('C' if k[1]==c else names[k[1]])}: {w}")
    h2 = cle([v for v in nodes if v not in C] + [c], W2)
    res = {v: head[v] for v in C}
    for v, u in h2.items():
        ou, ov = origin[(u, v)]
        res[ov] = ou
    return res

tree = cle([0, 1, 2, 3], W)
print("MST:", ", ".join(f"{names[h]} -> {names[d]}" for d, h in sorted(tree.items())), "| score", sum(W[(h, d)] for d, h in tree.items()))

# brute force over all head assignments that form a tree
best = None
for hs in product([0, 1, 2, 3], repeat=3):
    head = {d: h for d, h in zip([1, 2, 3], hs)}
    if any(d == h or (h, d) not in W for d, h in head.items()): continue
    if find_cycle(head): continue
    sc = sum(W[(h, d)] for d, h in head.items())
    if best is None or sc > best[0]: best = (sc, head)
print("brute-force best score:", best[0])
